    {"id": "ERZ_SCHLACKE:sitzordnung","meinung": "Wir sollten einen freien Blick auf die Tafel ermöglichen. Ziel: die Tafel von jedem Platz gut erkennen.","gruende": [{"text": "… weil keiner beim Lesen um andere herumsehen muss.","erz": true,"info": "Dieser Grund erklärt das Ziel: die Tafel von jedem Platz gut erkennen.","warum": [{"text": "Mit freier Sicht müssen wir nicht um andere herumsehen.","ok": true},{"text": "Nach dem Umstellen können wir unsere Freunde leichter sehen.","ok": false},{"text": "Die Tafel hängt an der vorderen Wand unseres Klassenraums.","ok": false}]},{"text": "Ein freies Sichtfeld hilft auch den Kindern in der letzten Reihe.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Mit freier Sicht müssen wir nicht um andere herumsehen.","ok": true},{"text": "Nach dem Umstellen können wir unsere Freunde leichter sehen.","ok": false},{"text": "Die Tafel hängt an der vorderen Wand unseres Klassenraums.","ok": false}]},{"text": "… weil wir unsere Freunde im Raum leichter sehen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil die Tafel vorne an der Wand unseres Raums hängt.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:klassenregel","meinung": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen. Ziel: leise Stimmen im Klassenrat besser hören.","gruende": [{"text": "… weil jeder reden kann, ohne von anderen übertönt zu werden.","erz": true,"info": "Dieser Grund erklärt das Ziel: leise Stimmen im Klassenrat besser hören.","warum": [{"text": "In der Reihenfolge übertönen andere keine leisen Stimmen.","ok": true},{"text": "Vor dem Sprechen können wir unsere Beiträge aufschreiben.","ok": false},{"text": "Im Klassenrat sprechen mehrere Kinder nacheinander über ein Thema.","ok": false}]},{"text": "Wer auf seinen Einsatz wartet, überdeckt die leise Stimme nicht.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "In der Reihenfolge übertönen andere keine leisen Stimmen.","ok": true},{"text": "Vor dem Sprechen können wir unsere Beiträge aufschreiben.","ok": false},{"text": "Im Klassenrat sprechen mehrere Kinder nacheinander über ein Thema.","ok": false}]},{"text": "… weil wir unsere Beiträge dabei vorher aufschreiben können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil im Klassenrat mehrere Kinder nacheinander sprechen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:dienste","meinung": "Wir sollten die Klassendienste jede Woche wechseln. Ziel: die Arbeit in der Klasse fair verteilen.","gruende": [{"text": "… weil nicht jede Woche dieselben Kinder alles erledigen.","erz": true,"info": "Dieser Grund erklärt das Ziel: die Arbeit in der Klasse fair verteilen.","warum": [{"text": "Beim Wechsel erledigen nicht immer dieselben Kinder die Arbeit.","ok": true},{"text": "Durch den Wechsel lernen wir unterschiedliche Dienste kennen.","ok": false},{"text": "Auf dem Dienstplan stehen in jeder Woche andere Kindernamen.","ok": false}]},{"text": "Auch unbeliebte Dienste werden beim Wechsel von allen übernommen.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Beim Wechsel erledigen nicht immer dieselben Kinder die Arbeit.","ok": true},{"text": "Durch den Wechsel lernen wir unterschiedliche Dienste kennen.","ok": false},{"text": "Auf dem Dienstplan stehen in jeder Woche andere Kindernamen.","ok": false}]},{"text": "… weil wir verschiedene Aufgaben im Klassenraum kennenlernen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil jede Woche neue Namen auf unserem Dienstplan stehen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:klassenfahrt","meinung": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen. Ziel: uns als Klasse besser kennenlernen.","gruende": [{"text": "… weil wir beim Lösen einer Aufgabe aufeinander angewiesen sind.","erz": true,"info": "Dieser Grund erklärt das Ziel: uns als Klasse besser kennenlernen.","warum": [{"text": "Bei gemeinsamen Aufgaben sind wir aufeinander angewiesen.","ok": true},{"text": "Auf der Fahrt können wir die Wege um die Unterkunft erkunden.","ok": false},{"text": "Eine Klassenfahrt dauert meist mehrere aufeinanderfolgende Tage.","ok": false}]},{"text": "Bei gemeinsamen Aufgaben hört man auch die Ideen neuer Partner.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Bei gemeinsamen Aufgaben sind wir aufeinander angewiesen.","ok": true},{"text": "Auf der Fahrt können wir die Wege um die Unterkunft erkunden.","ok": false},{"text": "Eine Klassenfahrt dauert meist mehrere aufeinanderfolgende Tage.","ok": false}]},{"text": "… weil wir dabei die Wege rund um die Unterkunft erkunden.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil eine Klassenfahrt meist mehrere Tage hintereinander dauert.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:schulhof","meinung": "Wir sollten Spielgeräte in der Pause ausleihen können. Ziel: mehr Kindern verschiedene Spiele ermöglichen.","gruende": [{"text": "… weil auch Kinder ohne eigenes Gerät etwas ausprobieren können.","erz": true,"info": "Dieser Grund erklärt das Ziel: mehr Kindern verschiedene Spiele ermöglichen.","warum": [{"text": "Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ok": true},{"text": "Bei der Ausgabe lernen wir die Namen anderer Kinder kennen.","ok": false},{"text": "Die ausgeliehenen Geräte werden am Ende der Pause zurückgegeben.","ok": false}]},{"text": "Fehlende eigene Spielsachen schließen dann niemanden vom Spiel aus.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ok": true},{"text": "Bei der Ausgabe lernen wir die Namen anderer Kinder kennen.","ok": false},{"text": "Die ausgeliehenen Geräte werden am Ende der Pause zurückgegeben.","ok": false}]},{"text": "… weil wir beim Ausleihen die Namen der anderen besser lernen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil die ausgeliehenen Geräte am Ende zurückgegeben werden.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:sport","meinung": "Wir sollten im Sport verschiedene Spielarten ausprobieren. Ziel: unterschiedliche Stärken der Kinder entdecken.","gruende": [{"text": "… weil nicht in jedem Spiel dieselben Fähigkeiten zählen.","erz": true,"info": "Dieser Grund erklärt das Ziel: unterschiedliche Stärken der Kinder entdecken.","warum": [{"text": "Bei verschiedenen Spielen zählen unterschiedliche Fähigkeiten.","ok": true},{"text": "Durch neue Spiele lernen wir verschiedene Spielnamen kennen.","ok": false},{"text": "Zu verschiedenen Spielen gehören eigene Regeln und Materialien.","ok": false}]},{"text": "Wer langsam läuft, kann bei einer anderen Aufgabe trotzdem helfen.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Bei verschiedenen Spielen zählen unterschiedliche Fähigkeiten.","ok": true},{"text": "Durch neue Spiele lernen wir verschiedene Spielnamen kennen.","ok": false},{"text": "Zu verschiedenen Spielen gehören eigene Regeln und Materialien.","ok": false}]},{"text": "… weil wir dabei die Namen vieler neuer Spiele kennenlernen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil verschiedene Sportspiele eigene Regeln und Materialien haben.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:ags","meinung": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten. Ziel: eine passende AG auswählen.","gruende": [{"text": "… weil wir vor der Wahl die Tätigkeit selbst ausprobieren.","erz": true,"info": "Dieser Grund erklärt das Ziel: eine passende AG auswählen.","warum": [{"text": "Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ok": true},{"text": "Beim Schnuppern lernen wir Kinder aus anderen Klassen kennen.","ok": false},{"text": "Die AGs finden jede Woche nach dem normalen Unterricht statt.","ok": false}]},{"text": "Ein eigener Versuch zeigt besser als ein Name, was man gern macht.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ok": true},{"text": "Beim Schnuppern lernen wir Kinder aus anderen Klassen kennen.","ok": false},{"text": "Die AGs finden jede Woche nach dem normalen Unterricht statt.","ok": false}]},{"text": "… weil wir dabei Kinder aus anderen Klassen kennenlernen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil die AGs jede Woche am Nachmittag stattfinden.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:handys","meinung": "Wir sollten Handys während der Gruppenarbeit weglegen. Ziel: in der Gruppe aufmerksam zusammenarbeiten.","gruende": [{"text": "… weil keine Nachricht mitten im Gespräch unsere Aufmerksamkeit ablenkt.","erz": true,"info": "Dieser Grund erklärt das Ziel: in der Gruppe aufmerksam zusammenarbeiten.","warum": [{"text": "Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ok": true},{"text": "In der Tasche können die Geräte nicht vom Gruppentisch fallen.","ok": false},{"text": "Während der Gruppenarbeit liegen die Handys in unseren Taschen.","ok": false}]},{"text": "Ohne Blick aufs Display bemerkt man Fragen der anderen schneller.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ok": true},{"text": "In der Tasche können die Geräte nicht vom Gruppentisch fallen.","ok": false},{"text": "Während der Gruppenarbeit liegen die Handys in unseren Taschen.","ok": false}]},{"text": "… weil wir die Geräte dann nicht aus Versehen fallen lassen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Handys während der Gruppenarbeit in den Taschen liegen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:haustiere","meinung": "Wir sollten vor dem Tierkauf einen Pflegeplan machen. Ziel: die tägliche Versorgung des Tieres sichern.","gruende": [{"text": "… weil wir vorher klären, wer jeden Tag welche Aufgabe übernimmt.","erz": true,"info": "Dieser Grund erklärt das Ziel: die tägliche Versorgung des Tieres sichern.","warum": [{"text": "Der Plan klärt für jeden Tag die Zuständigkeit bei der Pflege.","ok": true},{"text": "Beim Planen können wir uns einen Namen für das Tier überlegen.","ok": false},{"text": "In einem Pflegeplan stehen mehrere Aufgaben und Kindernamen.","ok": false}]},{"text": "Feste Zuständigkeiten helfen auch am Wochenende gegen vergessene Pflege.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Der Plan klärt für jeden Tag die Zuständigkeit bei der Pflege.","ok": true},{"text": "Beim Planen können wir uns einen Namen für das Tier überlegen.","ok": false},{"text": "In einem Pflegeplan stehen mehrere Aufgaben und Kindernamen.","ok": false}]},{"text": "… weil wir dabei überlegen, welchen Namen das Tier bekommt.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil ein Pflegeplan mehrere Aufgaben und Namen enthalten kann.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:freizeit","meinung": "Wir sollten einen Nachmittag ohne feste Termine lassen. Ziel: Zeit für eigene Ideen finden.","gruende": [{"text": "… weil wir selbst entscheiden können, was wir beginnen möchten.","erz": true,"info": "Dieser Grund erklärt das Ziel: Zeit für eigene Ideen finden.","warum": [{"text": "In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ok": true},{"text": "Für einen freien Nachmittag brauchen wir keine Kurstasche.","ok": false},{"text": "Ein freier Nachmittag hat keinen festen Platz im Kursplan.","ok": false}]},{"text": "Ohne fertigen Kursplan entsteht Raum für selbst gewählte Vorhaben.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ok": true},{"text": "Für einen freien Nachmittag brauchen wir keine Kurstasche.","ok": false},{"text": "Ein freier Nachmittag hat keinen festen Platz im Kursplan.","ok": false}]},{"text": "… weil wir dann keine Sporttasche für einen Kurs packen müssen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil ein freier Nachmittag nicht in unserem Kursplan steht.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:fahrrad","meinung": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen. Ziel: mit sicheren Fahrrädern losfahren.","gruende": [{"text": "… weil wir defekte Bremsen noch vor der Abfahrt entdecken.","erz": true,"info": "Dieser Grund erklärt das Ziel: mit sicheren Fahrrädern losfahren.","warum": [{"text": "Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ok": true},{"text": "Beim Treffen können wir die Fahrräder der anderen ansehen.","ok": false},{"text": "Vor dem Ausflug stehen viele Fahrräder auf unserem Schulhof.","ok": false}]},{"text": "Ein vorher entdeckter Fehler kann noch vor der Fahrt behoben werden.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ok": true},{"text": "Beim Treffen können wir die Fahrräder der anderen ansehen.","ok": false},{"text": "Vor dem Ausflug stehen viele Fahrräder auf unserem Schulhof.","ok": false}]},{"text": "… weil wir dabei die verschiedenen Fahrräder der Klasse ansehen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil vor dem Ausflug viele Fahrräder auf dem Schulhof stehen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:schulweg","meinung": "Wir sollten für den Schulweg sichere Querungen auswählen. Ziel: gefahrlos über viel befahrene Straßen kommen.","gruende": [{"text": "… weil wir an übersichtlichen Stellen den Verkehr besser sehen.","erz": true,"info": "Dieser Grund erklärt das Ziel: gefahrlos über viel befahrene Straßen kommen.","warum": [{"text": "An freien Querungen können wir den Verkehr besser sehen.","ok": true},{"text": "Auf dem gewählten Schulweg treffen wir andere Kinder häufiger.","ok": false},{"text": "Auf unserem Schulweg müssen wir mehrere Straßen überqueren.","ok": false}]},{"text": "Gute Sicht lässt mehr Zeit, ein herannahendes Auto zu bemerken.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "An freien Querungen können wir den Verkehr besser sehen.","ok": true},{"text": "Auf dem gewählten Schulweg treffen wir andere Kinder häufiger.","ok": false},{"text": "Auf unserem Schulweg müssen wir mehrere Straßen überqueren.","ok": false}]},{"text": "… weil wir auf diesem Weg andere Kinder öfter treffen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil auf unserem Schulweg mehrere Straßen überquert werden.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:umwelt","meinung": "Wir sollten in leeren Klassenräumen das Licht ausschalten. Ziel: unnötigen Stromverbrauch vermeiden.","gruende": [{"text": "… weil leere Räume keine Beleuchtung zum Arbeiten brauchen.","erz": true,"info": "Dieser Grund erklärt das Ziel: unnötigen Stromverbrauch vermeiden.","warum": [{"text": "Ohne Menschen im Raum ist keine Beleuchtung zum Arbeiten nötig.","ok": true},{"text": "Das Ausschalten erinnert uns an das Ende der Arbeitsphase.","ok": false},{"text": "An der Decke unserer Klassenräume hängen mehrere Lampen.","ok": false}]},{"text": "Eine ausgeschaltete Lampe verbraucht in dieser Zeit keinen Strom.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Ohne Menschen im Raum ist keine Beleuchtung zum Arbeiten nötig.","ok": true},{"text": "Das Ausschalten erinnert uns an das Ende der Arbeitsphase.","ok": false},{"text": "An der Decke unserer Klassenräume hängen mehrere Lampen.","ok": false}]},{"text": "… weil wir dadurch an das Ende der Pause erinnert werden.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in unseren Klassenräumen mehrere Lampen an der Decke hängen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:muell","meinung": "Wir sollten Papier getrennt von Essensresten sammeln. Ziel: sauberes Papier wiederverwerten lassen.","gruende": [{"text": "… weil Essensreste das gesammelte Papier nicht verschmutzen.","erz": true,"info": "Dieser Grund erklärt das Ziel: sauberes Papier wiederverwerten lassen.","warum": [{"text": "Ohne Essensreste wird das gesammelte Papier nicht schmutzig.","ok": true},{"text": "Beim Trennen lernen wir unsere verschiedenen Abfalleimer kennen.","ok": false},{"text": "Papier und Essensreste gehören in unterschiedliche Abfalleimer.","ok": false}]},{"text": "Sauberes Altpapier lässt sich besser für neue Papierwaren nutzen.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Ohne Essensreste wird das gesammelte Papier nicht schmutzig.","ok": true},{"text": "Beim Trennen lernen wir unsere verschiedenen Abfalleimer kennen.","ok": false},{"text": "Papier und Essensreste gehören in unterschiedliche Abfalleimer.","ok": false}]},{"text": "… weil wir dadurch unsere verschiedenen Abfalleimer kennenlernen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Papier und Essensreste in verschiedene Eimer gehören.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:ausflug","meinung": "Wir sollten Ausflugsziele mit dem Bus erreichen können. Ziel: allen Kindern die Teilnahme ermöglichen.","gruende": [{"text": "… weil niemand für die Anfahrt ein eigenes Auto braucht.","erz": true,"info": "Dieser Grund erklärt das Ziel: allen Kindern die Teilnahme ermöglichen.","warum": [{"text": "Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ok": true},{"text": "Bei der Busfahrt können wir die Landschaft unterwegs ansehen.","ok": false},{"text": "Der Bus fährt an einer Haltestelle vor unserer Schule ab.","ok": false}]},{"text": "Eine gemeinsame Anfahrt hängt nicht vom Auto der Eltern ab.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ok": true},{"text": "Bei der Busfahrt können wir die Landschaft unterwegs ansehen.","ok": false},{"text": "Der Bus fährt an einer Haltestelle vor unserer Schule ab.","ok": false}]},{"text": "… weil wir während der Fahrt die Landschaft anschauen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil der Bus an einer Haltestelle vor unserer Schule abfährt.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:klassenfest","meinung": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten. Ziel: jedem Kind eine passende Beteiligung ermöglichen.","gruende": [{"text": "… weil auch Kinder ohne Bühnenmut einen Beitrag leisten können.","erz": true,"info": "Dieser Grund erklärt das Ziel: jedem Kind eine passende Beteiligung ermöglichen.","warum": [{"text": "Auch ohne Bühnenmut können Kinder einen Beitrag leisten.","ok": true},{"text": "Bei verschiedenen Aufgaben sammeln wir mehr Ideen für das Fest.","ok": false},{"text": "Beim Klassenfest müssen mehrere Aufgaben gleichzeitig erledigt werden.","ok": false}]},{"text": "Wer nicht vor allen sprechen will, hilft trotzdem bei der Vorbereitung.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Auch ohne Bühnenmut können Kinder einen Beitrag leisten.","ok": true},{"text": "Bei verschiedenen Aufgaben sammeln wir mehr Ideen für das Fest.","ok": false},{"text": "Beim Klassenfest müssen mehrere Aufgaben gleichzeitig erledigt werden.","ok": false}]},{"text": "… weil wir dadurch mehr verschiedene Dinge für das Fest sammeln.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil beim Klassenfest mehrere Aufgaben nebeneinander anfallen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:gruppenarbeit","meinung": "Wir sollten in Gruppen klare Aufgaben absprechen. Ziel: doppelte Arbeit und vergessene Teile vermeiden.","gruende": [{"text": "… weil jeder weiß, welchen Teil der Aufgabe er übernimmt.","erz": true,"info": "Dieser Grund erklärt das Ziel: doppelte Arbeit und vergessene Teile vermeiden.","warum": [{"text": "Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ok": true},{"text": "Bei der Absprache können wir mit neuen Partnern sprechen.","ok": false},{"text": "In einer Arbeitsgruppe sitzen mehrere Kinder an einem Tisch.","ok": false}]},{"text": "Klare Zuständigkeiten zeigen, welcher Teil noch nicht bearbeitet ist.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ok": true},{"text": "Bei der Absprache können wir mit neuen Partnern sprechen.","ok": false},{"text": "In einer Arbeitsgruppe sitzen mehrere Kinder an einem Tisch.","ok": false}]},{"text": "… weil wir dadurch öfter mit neuen Partnern sprechen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in unserer Gruppe mehrere Kinder an einem Tisch sitzen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:bibliothek","meinung": "Wir sollten Bücher in der Klassenbibliothek beschriften. Ziel: passende Bücher schneller finden.","gruende": [{"text": "… weil wir am Schild sofort das Thema eines Regals erkennen.","erz": true,"info": "Dieser Grund erklärt das Ziel: passende Bücher schneller finden.","warum": [{"text": "Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ok": true},{"text": "Mit selbst gemalten Schildern können wir Bilder im Raum zeigen.","ok": false},{"text": "Die Bücher unserer Klassenbibliothek stehen in mehreren Regalen.","ok": false}]},{"text": "Wer ein Thema sucht, muss dann nicht jedes Buch einzeln herausziehen.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ok": true},{"text": "Mit selbst gemalten Schildern können wir Bilder im Raum zeigen.","ok": false},{"text": "Die Bücher unserer Klassenbibliothek stehen in mehreren Regalen.","ok": false}]},{"text": "… weil wir unsere selbst gemalten Schilder im Raum zeigen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Bücher in unserer Klassenbibliothek in Regalen stehen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:schulessen","meinung": "Wir sollten beim Schulessen kleine erste Portionen wählen. Ziel: weniger gutes Essen wegwerfen.","gruende": [{"text": "… weil wir erst nachnehmen, wenn wir noch Hunger haben.","erz": true,"info": "Dieser Grund erklärt das Ziel: weniger gutes Essen wegwerfen.","warum": [{"text": "Beim Nachnehmen passt die Essensmenge besser zum Hunger.","ok": true},{"text": "Mit kleinen Portionen können wir verschiedene Teller erproben.","ok": false},{"text": "An der Ausgabe stehen für die Kinder mehrere Stapel Teller bereit.","ok": false}]},{"text": "Auf dem Teller bleibt weniger zurück, wenn die Menge zum Hunger passt.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Beim Nachnehmen passt die Essensmenge besser zum Hunger.","ok": true},{"text": "Mit kleinen Portionen können wir verschiedene Teller erproben.","ok": false},{"text": "An der Ausgabe stehen für die Kinder mehrere Stapel Teller bereit.","ok": false}]},{"text": "… weil wir dadurch verschiedene Tellergrößen ausprobieren können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil beim Mittagessen Teller an der Ausgabe bereitstehen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:trinken","meinung": "Wir sollten Wasserflaschen im Klassenraum auffüllen können. Ziel: beim Lernen genug Wasser trinken.","gruende": [{"text": "… weil leere Flaschen auch während des Schultags wieder gefüllt werden.","erz": true,"info": "Dieser Grund erklärt das Ziel: beim Lernen genug Wasser trinken.","warum": [{"text": "An der Füllstelle werden leere Flaschen wieder gefüllt.","ok": true},{"text": "Mit eigenen Flaschen müssen wir keine fremden Becher benutzen.","ok": false},{"text": "Unsere Trinkflaschen haben verschiedene Größen und Farben.","ok": false}]},{"text": "Eine erreichbare Füllstelle hilft auch nach einer vergessenen Füllung.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "An der Füllstelle werden leere Flaschen wieder gefüllt.","ok": true},{"text": "Mit eigenen Flaschen müssen wir keine fremden Becher benutzen.","ok": false},{"text": "Unsere Trinkflaschen haben verschiedene Größen und Farben.","ok": false}]},{"text": "… weil wir unsere Flaschen nicht mit anderen verwechseln müssen.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil unsere Trinkflaschen verschiedene Farben und Größen haben.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:lesezeit","meinung": "Wir sollten eine kurze stille Lesezeit einführen. Ziel: ohne Unterbrechung in Geschichten eintauchen.","gruende": [{"text": "… weil alle gleichzeitig lesen und niemand dazwischen spricht.","erz": true,"info": "Dieser Grund erklärt das Ziel: ohne Unterbrechung in Geschichten eintauchen.","warum": [{"text": "Wenn alle still lesen, spricht niemand in die Geschichte hinein.","ok": true},{"text": "In der Lesezeit können wir unsere Lieblingsbücher zeigen.","ok": false},{"text": "In der Lesezeit liegen viele Bücher auf den Tischen im Raum.","ok": false}]},{"text": "Stille hilft, den Zusammenhang zwischen mehreren Seiten zu behalten.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Wenn alle still lesen, spricht niemand in die Geschichte hinein.","ok": true},{"text": "In der Lesezeit können wir unsere Lieblingsbücher zeigen.","ok": false},{"text": "In der Lesezeit liegen viele Bücher auf den Tischen im Raum.","ok": false}]},{"text": "… weil wir dabei unsere mitgebrachten Lieblingsbücher zeigen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in der Lesezeit Bücher auf unseren Tischen liegen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:partnerwahl","meinung": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen. Ziel: mit verschiedenen Kindern zusammenarbeiten lernen.","gruende": [{"text": "… weil wir auch mit Kindern außerhalb des Freundeskreises üben.","erz": true,"info": "Dieser Grund erklärt das Ziel: mit verschiedenen Kindern zusammenarbeiten lernen.","warum": [{"text": "Durch Lose üben wir auch mit Kindern außerhalb unserer Freunde.","ok": true},{"text": "Beim Losen können wir unsere eigenen Namenskärtchen nutzen.","ok": false},{"text": "Bei einer Partneraufgabe arbeiten jeweils zwei Kinder zusammen.","ok": false}]},{"text": "Neue Partner zeigen, wie andere Kinder an dieselbe Aufgabe herangehen.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Durch Lose üben wir auch mit Kindern außerhalb unserer Freunde.","ok": true},{"text": "Beim Losen können wir unsere eigenen Namenskärtchen nutzen.","ok": false},{"text": "Bei einer Partneraufgabe arbeiten jeweils zwei Kinder zusammen.","ok": false}]},{"text": "… weil wir durch das Losen unsere Namenskärtchen nutzen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil bei Partneraufgaben jeweils zwei Kinder zusammenarbeiten.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:ordnung","meinung": "Wir sollten gemeinsam benutztes Material fest einsortieren. Ziel: benötigte Sachen ohne langes Suchen finden.","gruende": [{"text": "… weil jeder den gleichen Platz für Schere und Kleber kennt.","erz": true,"info": "Dieser Grund erklärt das Ziel: benötigte Sachen ohne langes Suchen finden.","warum": [{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": true},{"text": "Beim Einsortieren können wir unsere Materialkisten bemalen.","ok": false},{"text": "Scheren und Kleber gehören gemeinsam zu unserem Bastelmaterial.","ok": false}]},{"text": "Ein fester Platz hilft auch Kindern, die das Material nicht weggeräumt haben.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": true},{"text": "Beim Einsortieren können wir unsere Materialkisten bemalen.","ok": false},{"text": "Scheren und Kleber gehören gemeinsam zu unserem Bastelmaterial.","ok": false}]},{"text": "… weil wir dabei unsere Materialkisten neu bemalen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Scheren und Kleber zusammen zu unserem Bastelmaterial gehören.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:spielregeln","meinung": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären. Ziel: Streit über unklare Entscheidungen vermeiden.","gruende": [{"text": "… weil wir schon vor dem Spiel wissen, welche Regeln gelten.","erz": true,"info": "Dieser Grund erklärt das Ziel: Streit über unklare Entscheidungen vermeiden.","warum": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true},{"text": "Vor dem Turnier erfahren wir die Namen der Mannschaften.","ok": false},{"text": "Bei einem Turnier spielen mehrere Mannschaften gegeneinander.","ok": false}]},{"text": "Eine bekannte Regel bietet beiden Seiten dieselbe Grundlage bei Streit.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true},{"text": "Vor dem Turnier erfahren wir die Namen der Mannschaften.","ok": false},{"text": "Bei einem Turnier spielen mehrere Mannschaften gegeneinander.","ok": false}]},{"text": "… weil wir dabei die Namen der anderen Mannschaften erfahren.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil zu einem Turnier mehrere Spiele zwischen Teams gehören.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:radstaender","meinung": "Wir sollten Fahrräder an festen Plätzen abstellen. Ziel: den Eingang zur Schule frei halten.","gruende": [{"text": "… weil kein Rad mitten im Weg vor der Eingangstür steht.","erz": true,"info": "Dieser Grund erklärt das Ziel: den Eingang zur Schule frei halten.","warum": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true},{"text": "Bei festen Plätzen finden wir die Räder unserer Freunde leichter.","ok": false},{"text": "Die Fahrradständer unserer Schule stehen neben dem Eingang.","ok": false}]},{"text": "Ein freier Eingang lässt auch mit einer großen Tasche genug Durchgang.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true},{"text": "Bei festen Plätzen finden wir die Räder unserer Freunde leichter.","ok": false},{"text": "Die Fahrradständer unserer Schule stehen neben dem Eingang.","ok": false}]},{"text": "… weil wir dort die Fahrräder unserer Freunde wiederfinden können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil unsere Schule mehrere Fahrradständer neben dem Eingang hat.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:tauschregal","meinung": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen. Ziel: gut erhaltene Dinge länger nutzen.","gruende": [{"text": "… weil andere Kinder noch verwendbare Sachen weiterbenutzen können.","erz": true,"info": "Dieser Grund erklärt das Ziel: gut erhaltene Dinge länger nutzen.","warum": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true},{"text": "Beim Tauschen entdecken wir verschiedene Farben und Muster.","ok": false},{"text": "In einem Tauschregal liegen verschiedene Sachen zum Mitnehmen.","ok": false}]},{"text": "Was weiterverwendet wird, muss nicht gleich neu gekauft werden.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true},{"text": "Beim Tauschen entdecken wir verschiedene Farben und Muster.","ok": false},{"text": "In einem Tauschregal liegen verschiedene Sachen zum Mitnehmen.","ok": false}]},{"text": "… weil wir dabei verschiedene Farben und Muster entdecken.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in einem Tauschregal Sachen zum Mitnehmen bereitliegen.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "ERZ_SCHLACKE:lernpause","meinung": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Ziel: nach langem Sitzen wieder aufmerksam arbeiten.","gruende": [{"text": "… weil wir die sitzende Haltung kurz unterbrechen können.","erz": true,"info": "Dieser Grund erklärt das Ziel: nach langem Sitzen wieder aufmerksam arbeiten.","warum": [{"text": "In Bewegungspausen unterbrechen wir das lange Sitzen.","ok": true},{"text": "In der Pause können wir unsere gewählten Bewegungen zeigen.","ok": false},{"text": "Eine Bewegungspause unterbricht unsere lange Arbeitsphase.","ok": false}]},{"text": "Ein kurzer Wechsel der Haltung erleichtert einen neuen Arbeitsbeginn.","erz": true,"info": "Diese Stütze erklärt ebenfalls das genannte Ziel.","warum": [{"text": "In Bewegungspausen unterbrechen wir das lange Sitzen.","ok": true},{"text": "In der Pause können wir unsere gewählten Bewegungen zeigen.","ok": false},{"text": "Eine Bewegungspause unterbricht unsere lange Arbeitsphase.","ok": false}]},{"text": "… weil wir dabei unsere selbst gewählten Bewegungen zeigen können.","erz": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil eine Bewegungspause unsere lange Arbeitsphase unterbricht.","erz": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]}
